def transform(g):
    H, W = len(g), len(g[0])
    line = next(r for r in range(H) if all(x == 2 for x in g[r]))
    out = [[0]*W for _ in range(H)]
    out[line] = g[line][:]
    for r in range(H):
        for c in range(W):
            if g[r][c] == 4 and r != line:
                nr = r + 1
                out[nr][c] = 4
                if nr == line - 1:
                    for dr, dc in ((-1,-1),(-1,1)):
                        rr, cc = nr + dr, c + dc
                        while 0 <= rr < H and 0 <= cc < W:
                            out[rr][cc] = 4
                            rr += dr; cc += dc
    return out

